            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Idź dokąd poszli tamci do ciemnego kresu po złote runo nicości twoją ostatnią nagrodę idź wyprostowany wśród tych co na kolanach wśród odwróconych plecami i obalonych w proch", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "idź bo tylko tak będziesz przyjęty do grona zimnych czaszek do grona twoich przodków: Gilgamesza Hektora Rolanda obrońców królestwa bez kresu i miasta popiołów Bądź wierny Idź", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Teraz kiedy zostaliśmy sami możemy porozmawiać książę jak mężczyzna z mężczyzną chociaż leżysz na schodach i widzisz tyle co martwa mrówka", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nigdy nie mogłem myśleć o twoich dłoniach bez uśmiechu i teraz kiedy leżą na kamieniu jak strącone gniazda są tak samo bezbronne jak przedtem To jest właśnie koniec Ręce leżą osobno Szpada leży osobno Osobno głowa i nogi rycerza w miękkich pantoflach", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Pogrzeb mieć będziesz żołnierski chociaż nie byłeś żołnierzem jest to jedyny rytuał na jakim trochę się znam", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "buty konie artyleryjskie werbel werbel wiem nic pięknego to będą moje manewry przed objęciem władzy trzeba wziąć miasto za gardło i wstrząsnąć nim trochę", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Tak czy owak musiałeś zginąć Hamlecie nie byłeś do życia wierzyłeś w kryształowe pojęcia a nie glinę ludzką żyłeś ciągłymi skurczami jak we śnie łowiłeś chimery łapczywie gryzłeś powietrze i natychmiast wymiotowałeś nie umiałeś żadnej ludzkiej rzeczy nawet oddychać nie umiałeś", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Teraz masz spokój Hamlecie zrobiłeś co do ciebie należało i masz spokój Reszta nie jest milczeniem ale należy do mnie", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "A zakopać cara ze złotym tronem – żal.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "co mnie właściwie obchodzi że te nogi należały do prawdziwej księżniczki reszta była hipotetyczna", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Co stało się z Barabaszem? Pytałem nikt nie wie Spuszczony z łańcucha wyszedł na białą ulicę mógł skręcić w prawo iść naprzód skręcić w lewo zakręcić się w kółko zapiać radośnie jak kogut", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Człowiek sam jest ślepy. Musi mieć wokół siebie lustra albo inne oczy. Kocha – to znaczy przygląda się sobie.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Dobranoc Marku lampę zgaś i zamknij książkę Już nad głową wznosi się srebrne larum gwiazd to niebo mówi obcą mową", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "gdy pogrążeni w sobie leżeliśmy blisko muszę zajrzeć do jej wnętrza zobaczyć co nosi w środku", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "gdy spała z otwartymi ustami zajrzałem i co i co jak myślicie co zobaczyłem spodziewałem się gałęzi spodziewałem się ptaka spodziewałem się domu nad wodą wielką i cichą A tam na szklanej płycie zobaczyłem parę jedwabnych pończoch mój Boże kupię jej te pończochy kupię", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Gdy wyschnie źródło gwiazd będziemy świecić nocom gdy skamienieje wiatr będziemy wzruszać powietrze.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Gdybym się drugi raz urodził może byłbym lepszy.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "I aby powiedzieć – kocham biegnę jak szalony zrywając naręcza ptaków.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "i jeśli Miasto padnie, a ocaleje jeden on będzie niósł Miasto w sobie po drogach wygnania on będzie Miasto", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "i tylko sny nasze nie zostały upokorzone", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "inne małe palce lewej ręki są zimną abstrakcją z moim mamy wspólną datę urodzin datę śmierci wspólną samotność", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "jedliśmy dużo jak zawsze wtedy kiedy nikt nie płaci", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "jeśli tematem sztuki będzie dzbanek rozbity mała rozbita dusza z wielkim żalem nad sobą to co po nas zostanie będzie jak płacz kochanków w małym brudnym hotelu kiedy świtają tapety", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Lekkim krokiem przechodzi od plamy do plamy od owocu do owocu", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Mój Boże żeby ona była trochę młodsza trochę ładniejsza szła z duchem czasu kołysała się w biodrach w takt modnej muzyki może wówczas pokochaliby ją prawdziwi mężczyźni generałowie atleci władzy despoci.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Mój głos wewnętrzny niczego nie doradza niczego nie odradza nie mówi ani tak ani nie jest słabo słyszalny i prawie nieartykułowalny.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Mój mały palec jest ciepły lekko zagięty do środka zakończony paznokciem składa się z trzech członów wyrasta wprost z dłoni gdyby był od niej oddzielony byłby sporym robakiem", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Mój ojciec bardzo lubił France’a i palił Przedni Macedoński w niebieskich chmurach aromatu smakował uśmiech w wargach wąskich", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Najpiękniejsza jest Nike w momencie kiedy się waha", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Napiętych myśli złamany łuk Marzenia, które ciało męczą. Śpię w cembrowinie twoich nóg Pod oczu twych zieloną rzęsą.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nie ma nic pospolitszego nad sny cesarzów.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nie mogę przypomnieć sobie jego twarzy stawał wysoko nade mną na długich rozstawionych nogach widziałem złoty łańcuszek popielaty surdut i chudą szyję do której przyszpilony był nieżywy krawat", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nie najlepiej urządził sobie życie niejaki Eric Blair na wszystkich zdjęciach twarz jego niecodziennie smutna. Lichy uczeń Eton – Oxford – potem służba w koloniach gdzie zmniejszył liczbę słoni o jednego słonia.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nie rozumiem, jak można pisać wiersze o księżycu. Jest tłusty i niechlujny. Dłubie w nosie kominów. Jego ulubione zajęcie to włazić pod łóżka i wąchać buty.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Niech mnie wydadzą dobre oczy pożerającym krajobrazom słowa co miały chronić ciało niech mi przepaści przyprowadzą.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nigdy cię mieć nie będę całej zawsze obrazek, uśmiech, skrawek.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nikomu nie przekażesz wiedzy twój tylko słuch jest i twój dotyk na nowo musi każdy stworzyć swą nieskończoność i początek.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Okolicznością łagodzącą jest fakt, że sztuka pochodzi z czasów zamierzchłych.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "On nas wprowadził przez złoty binokular w intymne życie naszego pradziadka pantofelka", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Pan Bóg kiedy budował świat marszczył czoło obliczał obliczał obliczał dlatego świat jest doskonały i nie można w nim mieszkać", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Panie, dzięki Ci składam za cały ten kram życia, w którym tonę od niepamiętnych czasów bez ratunku śmiertelnie skupiony na ciągłym poszukiwaniu drobiazgów.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Panie, nie zdążę już zadośćuczynić skrzywdzonym ani przeprosić tych wszystkich którym wyrządziłem zło dlatego smutna jest moja dusza.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Panie, wiem że dni moje są policzone zostało ich niewiele tyle żebym jeszcze zdążył zebrać piasek którym przykryją mi twarz", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Ponieważ żyli prawem wilka historia o nich głucho milczy pozostał po nich w kopnym śniegu żółtawy mocz i ten ślad wilczy", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Postarzał się car ojczulek, postarzał. Już nawet gołąbka własnymi rękami nie mógł zadusić. Siedział na tronie złoty i zimny. Tylko broda mu rosła do podłogi i niżej.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Przeleciał ptak przepływa obłok upada liść kiełkuje ślaz i cisza jest na wysokościach i dymi mgłą katyński las.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "STACJA ROVIGO. Niejasne skojarzenia. Dramat Goethego albo coś z Byrona. Przejeżdżałem przez Rovigo n razy i właśnie po raz n-ty zrozumiałem że w mojej geografii wewnętrznej jest to osobliwe miejsce chociaż na pewno ustępuje miejsca Florencji.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Starannie więc krawat i uśmiechają się do lustra. Bo teraz to jest łagodny jedwab, a wtedy za pierwszej miłości był sznur.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Suchy poemat moralisty tak – tak nie – nie.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "szedłem – przez wodospady schodów wiry morskich skrzydeł i barokowe niebo całe w bąblach aniołów – do ciebie", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Tak jak inni chciałem wiedzieć co stanie się ze mną po śmierci czy dostanę nowe mieszkanie i czy życie ma sens", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Tej garstce, która nas słucha, należy się piękno, ale także prawda…", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "To wcale nie wymagało wielkiego charakteru mieliśmy odrobinę niezbędnej odwagi lecz w gruncie rzeczy była to sprawa smaku Tak smaku który każe wyjść skrzywić się wycedzić szyderstwo choćby za to miał spaść bezcenny kapitel ciała głowa.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Trzeba świat pokrzepić fałszywymi łzami.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "tylko guziki nieugięte potężny głos zamilkłych chórów tylko guziki nieugięte guziki z płaszczy i mundurów", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "W czasie swej wielkiej mowy prokurator przebijał mnie na wylot żółtym wskazującym palcem mam powody by sądzić że wyglądałem nietęgo", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "w pierwszym rzędzie siedziała moja stara tłusta kobieta przebrana za moją matkę teatralnym gestem podnosiła chustkę do brudnych oczu ale nie płakała trwało to chyba długo nawet nie wiem jak długo", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "we mnie jest płomień który myśli i wiatr na pożar i na żagle", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Z faktu używania tych samych przekleństw i podobnych zaklęć miłosnych wyciąga się zbyt śmiałe wnioski także wspólna lektura szkolna nie powinna stanowić przesłanki wystarczającej aby zabić.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "z jego namowy w dziesiątym roku życia zostałem ojcem gdy po napiętym oczekiwaniu z kasztana zanurzonego w wodzie ukazał się żółty kiełek", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "z lekką głową papierosem za uchem i bez kropli nadziei w sercu", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Zapatrzony w Twoje oczy zaplątany w Twoje rzęsy.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Argument, że pułkownik Kukliński był zdrajcą, w myśl obowiązujących w PRL praw, jest formalnie słuszny, ale całkowicie absurdalny, gdyż musielibyśmy wyrzucić z podręczników szkolnych nazwiska Pułaskiego, Traugutta i Piłsudskiego.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Ale jeszcze pęta się we mnie złudzenie, że właśnie poezja jest próbą narzucenia odrobiny ładu i stwarza możliwość komunikowania się z ludźmi za pomocą zapisanego wzruszenia.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Chrystusa potrzebowałem zawsze, bo On rozumiał moje cierpienie.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Kultura to (…) budowanie wartości, dla których warto żyć.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Mam okresy, w których nie mogę pisać – kiedy po prostu czuję się zacieśniony do własnego cierpienia czy do własnego bólu, czy własnej niezgody. Wtedy przestaję pisać. Ale kiedy znajduję jakąś ścieżkę do świata, to staram się iść tą ścieżką.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Mody przemijają, żyją tylko wielcy zmarli i oni w końcu będą nas sądzić.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Naród, który traci pamięć, traci sumienie.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nie dialoguj z pokusą, bo przegrasz.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nie, jak będzie za ciężko, to wypije.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nie jestem autorytetem moralnym tak zwanym. Czasem piję, palę papierosy. (...) Jaki autorytet moralny może palić papierosy?", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Nie każda przewrotka jest od razu upadkiem.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Pisarz jest, a przynajmniej powinien być, po stronie poniżonych i pokrzywdzonych. Od tego nie mogą go zwolnić żadne instancje świeckie czy duchowne.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Płynie się zawsze do źródeł pod prąd, z prądem płyną śmiecie.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Poeta walczy z własnym cieniem. Poeta krzyczy, jak ptak w pustce.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Serce kamieni drży czasem jak serce małych zwierząt.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Sprawa pułkownika Kuklińskiego stała się sprawą nas wszystkich, apeluje do naszych sumień i obywatelskich postaw. Pułkownik Kukliński jest jednym z nas – cokolwiek chcieliby wydumać na ten temat ludzie złej woli i wygodnej obojętności.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Trudno zaiste pojąć, jak można ubiegać się o przyjęcie Polski do NATO, gdy odmawia się faktycznie powrotu do kraju temu, który pierwszy, na własne ryzyko, z narażeniem życia udowodnił, że Polska jest integralną częścią Zachodu i pragnie żyć we wspólnocie wolnych i demokratycznych państw.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Ukazuje się pismo „Mr Cogito”; o klubach nie słyszałem. Pomylił mnie pan chyba z „Playboyem”.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Uważam [je] za tchórzostwo.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Wątroba to nie gentleman.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Wielkie nazwiska uprawdopodobniają największe idioty­zmy, gdyż tłum ma naiwną pewność, że wielcy ludzie bredzić nie mogą.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "W mojej klasie było nas dwudziestu czterech i ja byłem najmniej zdolny; i z całej naszej klasy tylko ja jeden przeżyłem wojnę.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Wolność uzyskana bez kropli krwi nie jest żadną wolnością.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Boję się i drżę jak dziewica przed… no wiesz przed czym.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Ja się nie zmienię, Ty się nie zmienisz. Będą się dziewki przez nas rumienić Całuję Twoje słodkie wypukłości Twój Zbigniew.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Jestem samotnik. Nie odpisuję w zasadzie na listy. Przerażają mnie wieczory autorskie i spotkania. Więc czy nie lepiej nie popisywać się takim dziwadłem? Pozatem jestem mały, gruby i zawsze śpiący.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Mimo tych kłopotów, czuję się silny i chce mi się żyć, choć prawdę powiedziawszy nie bardzo wiem po co.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Najbardziej ucieszyło mnie Pana wyznanie, że jest Pan leniwy (podobnie jak ja), a więc mamy szansę dobrze się zrozumieć.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Na wódkę bym z Panem poszedł.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Oglądam zachody słońca i myślę o zbliżającej się starości.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Opaliłem się, ale wiem, że to trwa niedługo jak młodzieńcza miłość.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Podróżuję tylko koleją. Samolot napawa mnie zabobonnym lękiem.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "PS Bardzo mi smutno i chyba się dziś zaleję. Szkoda, że jest Pan tak daleko.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Wszystkie recenzje są pozytywne. Widomy znak, że książka jest zła.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Całuję Twą szyję i alabastrowe palce", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Jezioro Łabędzie mych dzikich snów, Kolumno i Różo mej tęsknoty, (...) rączki uprzejmie całuję.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Kochana Wdowo! Najdroższa Sieroto!!", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Kochana Wisełko, (...) Wesołych Świąt Twój pies Herbert", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Może niedługo umrę, ale pamiętaj że Cię kochałem zmysłowo choć bezinteresownie.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Mój Księżycu Luno moja, nie nie nie odczepiaj się ode mnie proszę. Bo to ja przywarłem do Ciebie i tak już zostanie do śmierci.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Pani Wisełce moc uścisków i całusuf szle", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Potrzebuję miłości i pieniędzy.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Ty Moja Nocy Świętojańska, nie masz pojęcia Serce jak tu zimno i francusko.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Wisełko brak mi Ciebie gdy świeci księżyc na niebie i jestem w wielkiej potrzebie.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Wisła, Ty moje Życie, ty moje tiu tiu tiu", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Zobaczysz, jak zostanę Panem Bogiem to wszyscy ludzie a nawet kobiety będą szczęśliwe.", Author = "Zbigniew Herbert" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zbigniew_Herbert", Text = "Z proletariackim pozdrowieniem Herbert pseudo Tramwajarz", Author = "Zbigniew Herbert" },
        };
    }
}